SELECT CAST(json_object('id',item_id,'digest',digest,'sender',json(sender),'acceptanceBound',acceptance_bound,'settlementBytes',settlement_bytes,'progress',json_object('kind',progress,'value',json_object('attempt',attempt,'outcome',json(CASE outcome_kind WHEN 'delivered' THEN json_object('kind',outcome_kind,'value',json_object('acceptance',json(outcome_acceptance))) WHEN 'refused' THEN json_object('kind',outcome_kind,'value',json_object('reason',json(CASE WHEN refusal_kind IN ('processingFailed','recipientRefused') THEN json_object('kind',refusal_kind,'value',json(CASE refusal_kind WHEN 'processingFailed' THEN json_object('kind',refusal_failure) WHEN 'recipientRefused' THEN json_object('code',refusal_code) ELSE 'null' END)) ELSE json_object('kind',refusal_kind) END))) WHEN 'prevented' THEN json_object('kind',outcome_kind,'value',json_object('cancel',outcome_cancel_item_id)) ELSE json_object('kind',outcome_kind) END))),'reportSeq',report_seq,'releaseRequested',json(CASE release_requested WHEN 0 THEN 'false' WHEN 1 THEN 'true' ELSE 'null' END)) AS TEXT) AS record FROM _fleet_sync_inbox_items UNION ALL SELECT CAST(json_object('item',item_id,'reportSeq',report_seq,'outcome',json(CASE outcome_kind WHEN 'delivered' THEN json_object('kind',outcome_kind,'value',json_object('acceptance',json(outcome_acceptance))) WHEN 'refused' THEN json_object('kind',outcome_kind,'value',json_object('reason',json(CASE refusal_kind WHEN 'recipientRefused' THEN json_object('kind',refusal_kind,'value',json_object('code',refusal_code)) WHEN 'processingFailed' THEN json_object('kind',refusal_kind,'value',json_object('kind',refusal_failure)) WHEN 'tooLarge' THEN json_object('kind',refusal_kind,'value',json_object('field',refusal_size_field)) WHEN 'itemConflict' THEN json_object('kind',refusal_kind,'value',json_object('existing',refusal_digest)) WHEN 'cancelAlreadyRequested' THEN json_object('kind',refusal_kind,'value',json_object('existing',json_object('item',refusal_item_id,'digest',refusal_digest))) ELSE json_object('kind',refusal_kind) END))) WHEN 'prevented' THEN json_object('kind',outcome_kind,'value',json_object('cancel',outcome_cancel_item_id)) WHEN 'tooLate' THEN json_object('kind',outcome_kind,'value',json_object('cancel',outcome_cancel_item_id,'at',outcome_too_late_at)) ELSE json_object('kind',outcome_kind) END)) AS TEXT) AS record FROM _fleet_sync_reports;
